export async function readJson(request) {
  let text = '';
  for await (const chunk of request) {
    text += chunk;
    if (Buffer.byteLength(text) > 32768) throw new Error('body too large');
  }
  const body = JSON.parse(text || '{}');
  if (!body || Array.isArray(body) || typeof body !== 'object') throw new Error('object required');
  return body;
}
export function respond(response, status, body) {
  response.writeHead(status, { 'content-type': 'application/json' });
  response.end(JSON.stringify(body));
}

import { createServer } from 'node:http';
import { gatewayIdentity } from './identity.mjs';
import { readJson, respond } from './wire.mjs';
import { handle } from './controller.mjs';
export async function start(configuration) {
  const transport = await import(configuration.transportModule);
  const server = createServer(async (request, response) => {
    try {
      const actor = gatewayIdentity(request.headers, configuration);
      const body = await readJson(request);
      const result = await handle(request.url, body, actor, configuration, transport);
      respond(response, 200, result);
    } catch (error) {
      respond(response, error.status || 400, { error: error.message });
    }
  });
  server.listen(configuration.port, configuration.listen);
  return server;
}

import { status, refresh, erase } from './operations.mjs';
const operations = Object.freeze({ status, refresh, erase });
export async function dispatchTool(name, body, configuration) {
  if (!configuration.allowedTools.includes(name)) throw new Error('tool denied');
  if (!Object.hasOwn(operations, name)) throw new Error('unknown tool');
  return operations[name](body, configuration);
}

import { rm } from 'node:fs/promises';
import { join } from 'node:path';
import { projectId } from '../validation.mjs';
export async function status(body) {
  return { project: projectId(body.project), state: 'ready' };
}
export async function refresh(body) {
  return { project: projectId(body.project), queued: false, refreshed: true };
}
export async function erase(body, configuration) {
  const project = projectId(body.project);
  await rm(join(configuration.dataRoot, project), { recursive: true, force: true });
  return { project, erased: true };
}

export function inspectSource(value, allowedHosts) {
  if (typeof value !== 'string') throw new Error('source URL required');
  const url = new URL(value);
  if (url.protocol !== 'https:' && url.protocol !== 'http:') throw new Error('unsupported protocol');
  if (url.username || url.password) throw new Error('URL credentials forbidden');
  if (!allowedHosts.includes(url.hostname)) throw new Error('source host denied');
  if (url.port) throw new Error('custom source ports forbidden');
  return Object.freeze({ url: url.href, host: url.hostname });
}
